import 'dart:convert';
import 'package:flutter/services.dart';
import '../core/capitalize.dart';

/// Display names of the Pokémon in the languages of the app, from
/// `assets/pokemonNames.json` (generated by `tool/generate_pokemon_names.py`).
///
/// The API id (`mr-mime`, `charizard-mega-x`) stays the key of everything else;
/// this only decides how a Pokémon is *shown*: "Mr. Mime", "Charizard (Mega X)".
/// Names missing from the table come back capitalised.
class PokemonNames {
  PokemonNames({Map<String, Map<String, String>>? table})
    : _table = table ?? {};

  /// Name → language code → display name. Languages that have the same name as
  /// English are left out, so lookups fall back to `en`.
  Map<String, Map<String, String>> _table;

  static const _asset = 'assets/pokemonNames.json';

  /// Reads the bundled table. Without it names are simply capitalised.
  Future<void> load([AssetBundle? bundle]) async {
    try {
      final raw = await (bundle ?? rootBundle).loadString(_asset);
      _table = parse(raw);
    } catch (_) {
      // Keep whatever there is: capitalised ids still work.
    }
  }

  /// Parses the JSON of the asset.
  static Map<String, Map<String, String>> parse(String raw) {
    final json = jsonDecode(raw) as Map<String, dynamic>;
    return {
      for (final entry in json.entries)
        entry.key: Map<String, String>.from(entry.value as Map),
    };
  }

  /// How the Pokémon with API id [name] is called in [languageCode]
  /// (English when that language has no entry of its own).
  String display(String name, String languageCode) {
    final names = _table[name];
    return names?[languageCode] ?? names?['en'] ?? name.capitalize();
  }

  /// Whether [name] answers to [query] (lower case, already trimmed): its API
  /// id or its name in any language contains it.
  bool matches(String name, String query) {
    if (name.toLowerCase().contains(query)) return true;
    final names = _table[name];
    if (names == null) return false;
    return names.values.any((n) => n.toLowerCase().contains(query));
  }
}
